const forecast = $input.first().json;
const daily = forecast.daily;
const dates = daily?.time;
const amounts = daily?.precipitation_sum;
const probabilities = daily?.precipitation_probability_max;
if (!Array.isArray(dates) || !Array.isArray(amounts) || !Array.isArray(probabilities) || dates.length === 0 || dates.length !== amounts.length || dates.length !== probabilities.length) {
  throw new Error('Previsão sem arrays diários alinhados.');
}
const alerts = [];
for (let index = 0; index < dates.length; index += 1) {
  const date = dates[index];
  const precipitation = amounts[index];
  const probability = probabilities[index];
  const parsedDate = typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date)
    ? new Date(`${date}T00:00:00.000Z`)
    : null;
  if (!parsedDate || Number.isNaN(parsedDate.getTime()) || parsedDate.toISOString().slice(0, 10) !== date || !Number.isFinite(precipitation) || precipitation < 0 || !Number.isInteger(probability) || probability < 0 || probability > 100) {
    throw new Error(`Medição inválida no índice ${index}.`);
  }
  alerts.push({
    id: `sp-centro-${date}`,
    area: 'Área demonstrativa — Centro, São Paulo',
    precipitation_mm: precipitation,
    probability_pct: probability,
    source_name: 'Open-Meteo',
    source_url: 'https://api.open-meteo.com/v1/forecast'
  });
}
return [{ json: { observed_at: new Date().toISOString(), alerts } }];
